// TieredAmount returns the charge for quantity units on a metered plan's tiers. Graduated: each unit is priced at the
// unit amount of the tier it falls in, and every tier that at least one unit falls in adds its flat amount. Volume: every
// unit is priced at the unit amount of the tier the quantity falls in, and that tier adds its flat amount. A tier's UpTo
// is inclusive, and a quantity of 0 costs 0.
func TieredAmount(tiers []store.Tier, mode store.TiersMode, quantity int64) int64 {
	if quantity <= 0 {
		return 0
	}
	if mode == store.Volume {
		for _, t := range tiers {
			if t.UpTo == nil || quantity <= *t.UpTo {
				return quantity*t.UnitAmount + t.FlatAmount
			}
		}
		return 0
	}
	var total, from int64 // units before the current tier
	for _, t := range tiers {
		if quantity <= from {
			break
		}
		top := quantity
		if t.UpTo != nil && *t.UpTo < quantity {
			top = *t.UpTo
		}
		total += (top-from)*t.UnitAmount + t.FlatAmount
		from = top
	}
	return total
}

