			tier.UpTo = &upTo
		}
		unit, err := money.ParseMajor(t.UnitAmount, c)
		if err != nil {
			return nil, fmt.Errorf("unit_amount: %w", err)
		}
		tier.UnitAmount = unit
		if t.FlatAmount != "" {
