func TestTieredMeteredBillsOneLine(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	upTo := func(n int64) *int64 { return &n }
	tiers := []store.Tier{{UpTo: upTo(100), UnitAmount: 200}, {UpTo: upTo(300), UnitAmount: 100, FlatAmount: 500}, {UnitAmount: 50}}
	p, err := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "API calls", Currency: money.USD, Interval: store.Monthly,
		UsageType: store.Metered, TiersMode: store.Graduated, Tiers: tiers}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	end := sub.CurrentPeriodEnd
	if _, err := e.Store.AddUsage(e.Acme.ID, sub.ID, 350, sub.CurrentPeriodStart, e.Clock.Now()); err != nil {
		t.Fatal(err)
	}
	e.Clock.Set(end)
	if _, err := e.Subs.RenewDue(ctx); err != nil {
